from __future__ import annotations

import json
from pathlib import Path


def write_report(out_dir: str | Path, payload: dict) -> None:
    out = Path(out_dir)
    out.mkdir(parents=True, exist_ok=True)
    (out / "report.json").write_text(json.dumps(payload, indent=2), encoding="utf-8")

    conservation = payload["conservation"]
    structural = payload["structural_reference"]
    lines = [
        "# Verification Report",
        "",
        "This report was generated by the deterministic synthetic verification pipeline. "
        "It validates the data transfer and structural reference tooling; it is **not** "
        "presented as an OpenFOAM/CalculiX solver result.",
        "",
        "## Coupling conservation",
        "",
        f"- CFD surface Fx: **{conservation['force_x_cfd_n']:.6f} N**",
        f"- Mapped Fx: **{conservation['force_x_mapped_n']:.6f} N**",
        f"- Force error: **{conservation['force_x_error_pct']:.4f}%**",
        f"- CFD root Mz: **{conservation['root_moment_z_cfd_nm']:.6f} N·m**",
        f"- Mapped root Mz: **{conservation['root_moment_z_mapped_nm']:.6f} N·m**",
        f"- Moment error: **{conservation['root_moment_z_error_pct']:.4f}%**",
        "",
        "## Structural reference",
        "",
        "- Euler-Bernoulli FE tip deflection under mapped load: "
        f"**{structural['tip_deflection_m'] * 1e3:.4f} mm**",
        "- Root bending stress estimate: "
        f"**{structural['root_bending_stress_pa'] / 1e6:.4f} MPa**",
        "",
        "## Verification boundary",
        "",
        "- Executed: Python mapping, force/moment conservation, beam FE reference, plots, tests.",
        "- Not executed in the build environment: OpenFOAM 13 CFD solve and CalculiX shell "
        "solve (binaries unavailable).",
        "",
    ]
    (out / "report.md").write_text("\n".join(lines), encoding="utf-8")
